-- Drops the users table and recreates it with a new primary key type,
-- re-migrating every foreign key reference across 6 other tables and
-- backfilling 40M existing rows with a generated UUID.
BEGIN;
DROP TABLE users CASCADE;
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT UNIQUE NOT NULL);
-- ... six more ALTER TABLE ... REFERENCES statements omitted for brevity ...
COMMIT;

